async function ITAKE(vb = true) {
  let cnt = 0, obj = 0, wloc = 0, tbl = 0;
  if (!(hasFlag(g.PRSO, TAKEBIT))) {
    if (vb) {
      await ROBOT_YUKS();
    }
    return false;
  } else if (eq(await CCOUNT(g.WINNER), g.NUM_EXT) || ((await CCOUNT(g.WINNER)) > g.NUM_EXT)) {
    if ((g.WINNER == WALDO) && hasFlag(SURGERY_HAND, WEARBIT)) {
      await ROBOT_TELL(get(g.EXTEN_QUIPS, 7));
    } else {
      await ROBOT_TELL(get(g.EXTEN_QUIPS, g.ROFF));
    }
    return false;
  } else if (!(loc(loc(g.PRSO)) == g.WINNER) && (((await WEIGHT(g.PRSO)) + (await WEIGHT(g.WINNER))) > g.LOAD_MAX)) {
    if (vb && !(g.PRSO == BROKEN_SHELF)) {
      (await ROBOT_TELL("I have a free extension, but I'm not strong enough to carry that", false));
      if (!(eq(await CCOUNT(g.WINNER), 0))) {
        tell(" and what I'm carrying");
      }
      tell(".\n");
    } else if (vb) {
      (await ROBOT_TELL("It's far too heavy."));
    }
    return M_FATAL;
  } else if (((cnt = await CCOUNT(g.WINNER)) > g.FUMBLE_NUMBER) && ((cnt * g.FUMBLE_PROB) > random(100))) {
    obj = first(g.WINNER);
    obj = next(obj);
    (await ROBOT_TELL("Oh, no. The ", false));
    await NDESC(obj);
    tell(" slips from my extenders while taking the ");
    await NDESC(g.PRSO);
    tell(" and both tumble to the ground.\n");
    wloc = loc(g.WINNER);
    if (hasFlag(wloc, RMUNGBIT)) {
      await PERFORM(V.DROP, obj);
      move(g.PRSO, g.WINNER);
      await PERFORM(V.DROP, g.PRSO);
    } else {
      move(obj, wloc);
      move(g.PRSO, wloc);
    }
    return M_FATAL;
  } else {
    if (g.PRSO == g.REDSET || g.PRSO == g.ORANGESET) {
      if (g.WINNER_HERE == TUBE1) {
        g.ORANGESET = false;
      } else if (g.WINNER_HERE == TUBE2) {
        g.REDSET = false;
      }
    }
    move(g.PRSO, g.WINNER);
    clearFlag(g.PRSO, NDESCBIT);
    setFlag(g.PRSO, TOUCHBIT);
    return true;
  }
}

