async function CCOUNT(obj) {
  let cnt = 0, x = 0;
  if (x = first(obj)) {
    loop1: for (;;) {
      if (!(hasFlag(x, NDESCBIT))) {
        cnt = cnt + 1;
      }
      if (!(x = next(x))) {
        break loop1;
      }
    }
  }
  return cnt;
}

async function CABLECOUNT(obj) {
  let cnt = 0, x = 0;
  if (x = first(obj)) {
    loop1: for (;;) {
      cnt = cnt + 1;
      if (!(x = next(x))) {
        break loop1;
      }
    }
  }
  return cnt;
}

async function WEIGHT(obj) {
  let cont = 0, wt = 0;
  if (cont = first(obj)) {
    loop1: for (;;) {
      wt = wt + (await WEIGHT(cont));
      if (!(cont = next(cont))) {
        break loop1;
      }
    }
  }
  return wt + getProp(obj, P.SIZE);
}

