async function DO_QUERY() {
  let str = 0, outstr = 0, count = 0;
  str = getProp(g.PRSO, P.CLC_TXT);
  outstr = get(g.PLUGOUTS, g.PLUGGED_IN);
  if (!str) {
    if (g.PLUGGED_IN == 1) {
      tell(S(outstr), "Index search indicates no data stored on that subject.\n");
    } else {
      tell(S(outstr), "No data available on that subject from the ", S(get(g.PLUG_LOCS, g.PLUGGED_IN)), "\n");
    }
    return true;
  } else if (g.PLUGGED_IN == 1) {
    for (;;) {
      count = count + 1;
      if (count == 4) {
        return true;
      }
      if (!(eq(get(str, count), 0))) {
        tell(S(outstr), "Data available from the ", S(get(g.PLUG_LOCS, count + 1)), "\n");
      }
    }
  } else {
    if (!(eq(str = get(str, g.PLUGGED_IN - 1), 0))) {
      tell(S(outstr), S(str), "\n");
      return true;
    } else {
      tell(S(outstr), "No data available on that subject at this peripheral.\n");
      return true;
    }
  }
}

