async function ROB(who, where = false, hide$ = false) {
  let n_ = 0, x = 0, robbed$ = false;
  x = first(who);
  for (;;) {
    if (!x) {
      return robbed$;
    }
    n_ = next(x);
    if (await RIPOFF(x, where)) {
      if (hide$) {
        setFlag(x, NDESCBIT);
      }
      robbed$ = x;
    }
    x = n_;
  }
}

async function RIPOFF(x, where) {
  if (!(loc(x) == where) && !(hasFlag(x, INVISIBLE)) && hasFlag(x, TOUCHBIT) && hasFlag(x, TAKEBIT)) {
    if (where) {
      move(x, where);
    } else {
      remove(x);
    }
    return true;
  } else {
    return false;
  }
}

