async function V_WALK_TO() {
  if (g.PRSO == CAR) {
    setVarIndirect(g.PRSO, loc(CAR));
  }
  if (g.PRSO == HELL) {
    tell("FC: What makes you think you're not already there?\n");
    return true;
  } else if (g.PRSO == g.WINNER_HERE || g.PRSO == g.WINNER) {
    return await ROBOT_TELL(get(g.WALK_INSULTS, g.ROFF));
  } else if (loc(g.PRSO) == ROOMS) {
    if (!(eq(get(g.FOLLOW_TBL, g.ROFF), 0))) {
      put(g.FOLLOW_TBL, g.ROFF, 0);
    }
    await KILL_GOAL(g.WINNER);
    await SET_GOAL(g.WINNER, g.PRSO);
    await DO_THE_TV();
    await ROBOT_TELL(get(g.ORDER_RCD, g.ROFF));
    return await CHECK_MORE$();
  } else if (getProp(g.PRSO, P.ROBOT)) {
    await SET_GOAL(g.WINNER, loc(g.PRSO));
    await DO_THE_TV();
    if (!(hasFlag(g.PRSO, CUTBIT))) {
      tell("FC: ");
      await NDESC(g.PRSO);
      tell("'s location: ");
    } else {
      tell("FC: ");
      await NDESC(g.PRSO);
      tell(" is non-functional. Last known location: ");
    }
    tell(D(loc(g.PRSO)), ". Establishing path...\n");
    await ROBOT_TELL(get(g.ORDER_RCD, g.ROFF));
    if (!(eq(get(g.FOLLOW_TBL, g.ROFF), 0))) {
      put(g.FOLLOW_TBL, g.ROFF, 0);
    }
    put(g.ROBOT_FOLLOW, g.ROFF, g.PRSO);
    return await CHECK_MORE$();
  } else if (loc(g.PRSO) == g.WINNER_HERE) {
    return (await ROBOT_TELL("It's right here."));
  } else {
    return (await ROBOT_TELL("You'll have to tell me where it is first."));
  }
}

