async function BIG_NUM_PRINT(num) {
  let temp = 0;
  if (num == 0) {
    tell("0");
    return true;
  } else if (num > 999) {
    temp = div(num, 1000);
    num = mod(num, 1000);
    tell(N(temp), ",");
    if (num == 0) {
      tell("000");
    } else if (num < 10) {
      tell("00", N(num));
    } else if (num < 100) {
      tell("0", N(num));
    } else {
      tell(N(num));
    }
  } else {
    tell(N(num));
  }
  tell(",000");
  return true;
}

