async function DEAD_FCN(rob = 0) {
  let count = 0, temp = 0, l = 0;
  if (!(rob == 0)) {
    tell("FC: ");
    await NDESC(rob);
    tell(" is no longer functional.\n");
  }
  if (g.OLD_WINNER) {
    temp = get(g.DEADBOTS, getProp(g.OLD_WINNER, P.ROBOT));
    if (temp < 30) {
      g.WINNER = g.OLD_WINNER;
      g.OLD_WINNER = false;
      g.WINNER_HERE = loc(l = loc(g.WINNER)) == ROOMS ? l : loc(l);
      g.ROFF = getProp(g.WINNER, P.ROBOT);
      g.HERE = g.WINNER;
      tell("FC: Cryolink reestablished to ");
      tell(D(g.WINNER), ".\n");
      g.QUOTE_FLAG = false;
      g.P_CONT = false;
      return M_FATAL;
    }
  }
  for (;;) {
    count = count + 1;
    if (count == 7) {
      tell("FC: There's no point in continuing. All the robots are history and, for that matter, so are the people on the surface.\n");
      await quit();
    }
    temp = get(g.DEADBOTS, count);
    if (temp < 30) {
      g.WINNER = get(g.NAME_TBL, count - 1);
      g.OLD_WINNER = false;
      g.WINNER_HERE = loc(l = loc(g.WINNER)) == ROOMS ? l : loc(l);
      g.ROFF = getProp(g.WINNER, P.ROBOT);
      g.HERE = g.WINNER;
      tell("FC: Cryolink established to ");
      tell(D(g.WINNER), ".\n");
      g.QUOTE_FLAG = false;
      g.P_CONT = false;
      return M_FATAL;
    }
  }
}

