async function I_WEATHER() {
  g.PRESSURE1 = await ADJUST_PRESSURE(g.PRESSURE1, get(g.DIALSETS, 1));
  g.PRESSURE2 = (await ADJUST_PRESSURE(g.PRESSURE2, get(g.DIALSETS, 2))) - g.DECAY;
  if (g.PRESSURE2 < 0) {
    g.PRESSURE2 = 0;
  }
  g.PRESSURE3 = await ADJUST_PRESSURE(g.PRESSURE3, get(g.DIALSETS, 3));
  g.WINDS = Math.abs(g.PRESSURE2 - g.PRESSURE3) + Math.abs(g.PRESSURE1 - g.PRESSURE2);
  g.DEGREES = 60 + ((div(g.PRESSURE1 + g.PRESSURE2 + g.PRESSURE3, 3) - 60) * 2);
  enable(await QUEUE(I_WEATHER.id, 5));
  return false;
}

async function ADJUST_PRESSURE(old, new_) {
  let adj = 0;
  if (old == new_) {
    return old;
  } else if (eq(adj = div(Math.abs(old - new_), 5), 0)) {
    adj = 1;
  }
  if (old > new_) {
    return old - adj;
  } else {
    return old + adj;
  }
}

