  tell(N(g.WINDS), " cycles.\n");
  tell("  Current surface casualties: ");
  await BIG_NUM_PRINT(g.TOTAL_SCORE);
  crlf();
  tell("  Projected casualties during recovery: ");
  g.DEGREES = g.SCORE * g.WINDS;
