    ml = Math.abs(g.MINERALS - MINERALS_OPT) + 0;
    ll = Math.abs(g.WATTS - WATTS_OPT) + 0;
    if (g.WATER_LEVEL > WATER_OPT) {
      (strw = "high");
    } else if (g.WATER_LEVEL == WATER_OPT) {
      (strw = " =");
    } else if ((strw = "low")) {
    }
    if (g.MINERALS > MINERALS_OPT) {
      (strm = "high");
    } else if (g.MINERALS == MINERALS_OPT) {
      (strm = " =");
    } else if ((strm = "low")) {
    }
    if (g.WATTS > WATTS_OPT) {
      (strl = "high");
    } else if (g.WATTS == WATTS_OPT) {
      (strl = " =");
    } else if ((strl = "low")) {
    }
    tell("Through the monitors I can see the following information:\n");
    await FIXED_FONT_ON();
    tell("\n           LEVEL  SETTING  OUTPUT\nWATER:      ");
