async function CIRCLE_FCN() {
  let count = 0, num_pressed = 0, premature = true;
  if (isVerb(V.PUSH)) {
    if (!(loc(FUSE) == MACHINE)) {
      (await ROBOT_TELL("Nothing is happening. I don't think it's working anymore."));
      return true;
    }
    if (hasFlag(g.PRSO, TOUCHBIT)) {
      tell("FC: That one has already been pressed.\n");
      return true;
    } else {
      setFlag(g.PRSO, TOUCHBIT);
    }
    if ((g.REDSET == REDWIRE) && (g.ORANGESET == ORANGE_WIRE)) {
      premature = false;
      if (g.PRSO == g.CODE1) {
        g.CODE_SET1 = true;
      } else if (g.PRSO == g.CODE2) {
        g.CODE_SET2 = true;
      }
    }
    loop1: for (;;) {
      if ((count = count + 1) > 8) {
        break loop1;
      } else {
        if (hasFlag(get(g.CODE_TBL, count), TOUCHBIT)) {
          num_pressed = num_pressed + 1;
        }
      }
    }
    if (num_pressed == 1) {
      if (premature) {
        tell("FC: Attempt for reset has been rejected. Code entry premature. FCs out of balance.\n");
        await RESET_CODES();
        return true;
      } else {
        tell("FC: First access code accepted. Enter second access code now.\n");
        return true;
      }
    } else if (num_pressed == 2) {
      tell("FC: Second access code accepted. \n");
      if (g.CODE_SET1 && g.CODE_SET2) {
        return await END_GAME();
      } else {
        tell("\nFC: Code recognition failed. Pattern entered does not match the reset code. Reset procedures aborted. New reset code being generated due to possible tampering.\n");
        await RESET_CODES();
        return await GENERATE_CODES();
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function RESET_CODES() {
  let count = 0;
  loop1: for (;;) {
    if ((count = count + 1) > 8) {
      break loop1;
    } else {
      clearFlag(get(g.CODE_TBL, count), TOUCHBIT);
    }
  }
  g.CODE_SET1 = false;
  g.CODE_SET2 = false;
  return true;
}

async function GENERATE_CODES() {
  g.CODE1 = await PICK_ONE(g.CODE_TBL);
  g.CODE2 = await PICK_ONE(g.CODE_TBL);
  loop1: for (;;) {
    if (g.CODE1 == g.CODE2) {
      g.CODE2 = await PICK_ONE(g.CODE_TBL);
    } else {
      break loop1;
    }
  }
  return await RESET_CODES();
}

async function KILL_GOAL(rbt, drag = false) {
  let gt = 0, offset = 0;
  offset = getProp(rbt, P.ROBOT);
  gt = get(g.GOAL_TABLES, offset);
  put(gt, GOAL_S, false);
  put(gt, GOAL_F, false);
  put(gt, GOAL_ENABLE, true);
  if (drag) {
    put(g.DRAG_TBL, offset, 0);
  }
  return false;
}

async function SET_GOAL(rbt, goal) {
  let here = loc(rbt), hl = 0, gl = 0, gt = 0;
  gt = get(g.GOAL_TABLES, getProp(rbt, P.ROBOT));
  put(gt, GOAL_I, (getProp(here, P.LINE) * 12) + (getProp(goal, P.LINE) * 2));
  put(gt, GOAL_S, getProp(goal, P.STATION));
  put(gt, GOAL_F, goal);
  put(gt, GOAL_ENABLE, true);
  return loc(rbt);
}

async function FOLLOW_GOAL(rbt) {
  let here = loc(rbt), line = 0, ln = 0, rm = 0, gt = 0, goal = 0, flg = 0, goal_flag = false, igoal = false, loc_ = 0, cnt = 1, dir = 0;
  gt = get(g.GOAL_TABLES, getProp(rbt, P.ROBOT));
  if (here == get(gt, GOAL_F)) {
    await ARRIVAL(rbt);
    if (!(rbt == PEOPLE)) {
      return true;
    } else {
      return false;
    }
  } else if (!(get(gt, GOAL_ENABLE))) {
    return false;
  }
  if (!(eq(loc_ = getProp(here, P.STATION), here))) {
    return await MOVE_RBT(rbt, loc_);
  }
  if (eq(goal = get(g.TRANSFER_TABLE, igoal = get(gt, GOAL_I)), 0)) {
    igoal = false;
    goal = get(gt, GOAL_S);
  }
  if (!goal) {
    return false;
  } else if (here == goal) {
    if (igoal) {
      if (!(flg = await MOVE_RBT(rbt, get(g.TRANSFER_TABLE, igoal + 1)))) {
        await SET_GOAL(rbt, get(gt, GOAL_F));
      }
      return flg;
    } else if (!(here == get(gt, GOAL_F))) {
      await MOVE_RBT(rbt, get(gt, GOAL_F));
      return await ARRIVAL(rbt);
    } else {
      return await ARRIVAL(rbt);
    }
  }
  line = await GET_LINE(getProp(goal, P.LINE));
  for (;;) {
    if (eq(rm = get(line, cnt), here)) {
      if (goal_flag) {
        loc_ = get(line, cnt - 3);
      } else {
        loc_ = get(line, cnt + 3);
      }
      return await MOVE_RBT(rbt, loc_);
    } else if (rm == goal) {
      goal_flag = true;
    }
    cnt = cnt + 3;
  }
}

async function STUCK(rbt, where) {
  let gt = 0, temp = 0, offset = 0;
  offset = getProp(rbt, P.ROBOT);
  gt = get(g.GOAL_TABLES, offset);
  temp = g.WINNER;
  await CHANGE_WINNER(rbt, true);
  if (g.WINNER == temp) {
    await ROBOT_TELL(get(g.STUCK_QUIPS, g.ROFF), false);
  } else {
    tell(S(get(g.INTER_TBL, g.ROFF)), " ", S(get(g.STUCK_QUIPS, g.ROFF)));
  }
  tell(D(loc(rbt)), " to ");
  if (g.WINNER == IRIS) {
    tell("Angling Corridor");
  } else {
    tell(D(where));
  }
  tell(". ", S(get(g.MORE_STUCKS, g.ROFF)), "\n");
  await KILL_GOAL(rbt);
  put(g.ROBOT_FOLLOW, offset, 0);
  put(g.FOLLOW_TBL, g.ROFF, 0);
  await CHANGE_WINNER(temp, true);
  return true;
}

async function MOVE_RBT(rbt, where) {
  let l = loc(rbt), count = 0, floc = 0, frob = 0;
  if (await MOVE_RBT$(rbt, l, where)) {
    return true;
  }
  loop1: for (;;) {
    count = count + 1;
    if (count == 7) {
      break loop1;
    }
    if (eq(get(g.FOLLOW_TBL, count), rbt)) {
      frob = get(g.NAME_TBL, count - 1);
      floc = loc(frob);
      if ((frob == IRIS) && (CORRIDOR_1 == where)) {
        await STUCK(IRIS, CPU_ROOM);
      } else {
        await MOVE_RBT$(frob, floc, where);
      }
    }
  }
  return false;
}

async function MOVE_RBT$(rbt, l, where) {
  if ((l == HUMAN_ENTRY || l == HALLWAY_JUNCTION) && (where == HUMAN_ENTRY || where == HALLWAY_JUNCTION) && !(g.WEDGE_PLACED == 2) && !(rbt == PEOPLE)) {
    await STUCK(rbt, where);
    return true;
  } else if ((l == CORRIDOR_4) && (where == ACIDMIST) && !g.ACID_FIXED && !(PEOPLE == rbt)) {
    if (eq(get(g.DEADBOTS, getProp(rbt, P.ROBOT)), 0)) {
      put(g.DEADBOTS, getProp(rbt, P.ROBOT), 1);
      await DO_THE_MOVE(rbt, l, where);
      return false;
    } else {
      await DO_THE_MOVE(rbt, l, where);
      return false;
    }
  } else if ((l == HALL_END || l == CAR_AREA) && (where == HALL_END || where == CAR_AREA)) {
    await STUCK(rbt, where);
    return true;
  } else if ((rbt == IRIS) && (l == CPU_ROOM || l == CORRIDOR_1) && (where == CORRIDOR_1 || where == CORRIDOR_2)) {
    move(IRIS, CPU_ROOM);
    setVarIndirect(where, CORRIDOR_1);
    setVarIndirect(l, CPU_ROOM);
    await STUCK(rbt, where);
    return true;
  } else {
    await DO_THE_MOVE(rbt, l, where);
    return false;
  }
}

async function DO_THE_MOVE(rbt, l, where) {
  let dragee = 0;
  move(rbt, where);
  if (rbt == g.WINNER) {
    g.WINNER_HERE = where;
  }
  put(g.LAST_ROOM, getProp(rbt, P.ROBOT), l);
  if (!(rbt == PEOPLE)) {
    if (!(eq(dragee = get(g.DRAG_TBL, getProp(rbt, P.ROBOT)), 0))) {
      move(dragee, where);
      put(g.LAST_ROOM, getProp(dragee, P.ROBOT), l);
    }
  }
  return false;
}

async function COR_DIR(here, there) {
  let cor = 0, rm = 0, past = 0, cnt = 2;
  cor = await GET_COR(getProp(there, P.CORRIDOR) & getProp(here, P.CORRIDOR));
  loop1: for (;;) {
    if (eq(rm = get(cor, cnt), here)) {
      past = 1;
      break loop1;
    } else if (rm == there) {
      break loop1;
    }
    cnt = cnt + 1;
  }
  return get(cor, past);
}

