async function G_ROBOT(rbt, garg) {
  let temp = 0, count = 0, chased = 0;
  if (garg == G_REACHED) {
    temp = g.WINNER;
    await CHANGE_WINNER(rbt, true);
    crlf();
    if (g.WINNER == temp) {
      await ROBOT_TELL(get(g.ARRIVAL_QUIPS, g.ROFF), false);
    } else {
      tell(S(get(g.INTER_TBL, g.ROFF)), " ", S(get(g.ARRIVAL_QUIPS, g.ROFF)));
    }
    await KILL_GOAL(g.WINNER, true);
    tell(D(loc(g.WINNER)), ".");
    if (!(eq(chased = get(g.ROBOT_FOLLOW, g.ROFF), 0))) {
      if (!(eq(loc(chased), loc(rbt)))) {
        tell(" Looks like I missed ");
        await NDESC(chased);
        tell(" though.\n");
      }
    }
    put(g.ROBOT_FOLLOW, getProp(rbt, P.ROBOT), 0);
    await apply(getProp(g.WINNER_HERE, P.ACTION), M_ENTER);
    crlf();
    await CHANGE_WINNER(temp, true);
    return M_FATAL;
  } else {
    return false;
  }
}

