async function V_CONFIGURE() {
  let count = 0, rbt = 0, rm = 0;
  if (g.MOVES > 1) {
    tell("You may only configure the game on the first move. Consult the manual for details.\n");
    return false;
  }
  g.SETUP_MODE = true;
  tell("Pick your poison.\nSpecify the name of a location for each of the following robots or DEAD if you would like to have the robot start out non-functional.\n");
  loop1: for (;;) {
    if ((count = count + 1) > 6) {
      break loop1;
    } else {
      rbt = get(g.NAME_TBL, count - 1);
      loop2: for (;;) {
        tell(S(get(g.ROBOT_NAMES, count)), " ");
        if (await PARSER()) {
          rm = get(g.P_TABLE, 1);
          if (rm == UD_TUBE) {
            put(g.DEADBOTS, count, 30);
            setFlag(rbt, CUTBIT);
            break loop2;
          } else if (loc(rm) == ROOMS) {
            if ((rbt == IRIS) && !(await IRIS_ALLOWED$(rm))) {
              tell("IRIS cannot leave the Monitor and Supply Area.\n");
            } else if ((rm == CAR_AREA || rm == BIO_INT) || (rm == BIO_LAB || rm == CRYOUNITS)) {
              tell("No robot is allowed to start in the Biological Areas.\n");
            } else if (rm == HELL) {
              tell("Come on. Get serious.\n");
            } else {
              move(rbt, rm);
              break loop2;
            }
          } else {
            tell("Specify the name of a location or the word DEAD.\n");
          }
        } else {
          tell("Specify the name of a location or the word DEAD.\n");
        }
      }
    }
  }
  loop3: for (;;) {
    tell("Surface-side systems tremor at which cycle? (1-100) >");
    if (await READ_NUMBER(1, 100)) {
      g.RTD_KILLS = g.P_NUMBER;
      await QUEUE(I_TREMOR2.id, g.RTD_KILLS);
      break loop3;
    }
  }
  loop4: for (;;) {
    tell("Cooling systems tremor at which cycle? (1-100) >");
    if (await READ_NUMBER(1, 100)) {
      g.ACID_KILLS = g.P_NUMBER;
      await QUEUE(I_TREMOR1.id, g.ACID_KILLS);
      break loop4;
    }
  }
  loop5: for (;;) {
    tell("Humans arrive at which cycle? (", N(g.ACID_KILLS), "-150) >");
    if (await READ_NUMBER(g.ACID_KILLS, 150)) {
      g.PEOPLE_APPEAR = g.P_NUMBER;
      await QUEUE(I_PEOPLE1.id, g.PEOPLE_APPEAR);
      break loop5;
    }
  }
  g.SETUP_MODE = false;
  tell("Configuration completed.\n\n");
  await V_ALL_REPORT_LOC();
  disable(await INT(I_IRIS_HINTS.id));
  disable(await INT(I_AUDA_HINTS.id));
  return true;
}

async function READ_NUMBER(mn, mx) {
  await read(g.P_INBUF, g.P_LEXV);
  if (await NUMBER$(P_LEXSTART)) {
    if (!(g.P_NUMBER < mn) && !(g.P_NUMBER > mx)) {
      return true;
    } else {
      tell("Enter a number between ", N(mn), " and ", N(mx), ".\n");
      return false;
    }
  } else {
    tell("Enter a number between ", N(mn), " and ", N(mx), ".\n");
    return false;
  }
}

async function IRIS_ALLOWED$(rm) {
  if ((rm == CPU_ROOM || rm == SERVO_SYSTEMS || rm == RTD_BANKS) || (rm == WEATHER_BANKS || rm == SUPPLIES_SOUTH || rm == SUPPLIES_MID) || (rm == SUPPLIES_NORTH)) {
    return true;
  } else {
    return false;
  }
}

